import sqlite3
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path
from typing import Any


_TABLE_ORDER = (
    "ACCT_MASTER",
    "CONT_MASTER",
    "ORD_HEADER",
    "ORD_LINE",
)

_COLUMNS = {
    "ACCT_MASTER": (
        "ACCT_ID",
        "ACCT_NM",
        "ACCT_TYP",
        "REGION_CD",
        "ANN_REV",
        "CURR_CD",
        "CRED_LIMIT",
        "CRED_HOLD",
        "CREATE_DT",
    ),
    "CONT_MASTER": (
        "CONT_ID",
        "ACCT_ID",
        "FRST_NM",
        "LAST_NM",
        "EMAIL_TX",
        "PREF_CH",
        "OPTOUT_FLG",
    ),
    "ORD_HEADER": (
        "ORD_ID",
        "ACCT_ID",
        "ORD_DT",
        "STAT_CD",
        "DISC_PCT",
        "TOT_AMT",
    ),
    "ORD_LINE": (
        "ORD_ID",
        "LINE_NO",
        "PROD_ID",
        "QTY",
        "UNIT_PRC",
        "EXT_AMT",
    ),
}

_NUMERIC_COLUMNS = {
    "ANN_REV",
    "CRED_LIMIT",
    "DISC_PCT",
    "TOT_AMT",
    "LINE_NO",
    "QTY",
    "UNIT_PRC",
    "EXT_AMT",
}

_MONETARY_COLUMNS = {
    "ANN_REV",
    "CRED_LIMIT",
    "TOT_AMT",
    "UNIT_PRC",
    "EXT_AMT",
}

_DATE_COLUMNS = {
    "CREATE_DT",
    "ORD_DT",
}

_BOOLEAN_COLUMNS = {
    "CRED_HOLD",
    "OPTOUT_FLG",
}

_PRIMARY_KEYS = {
    "ACCT_MASTER": ("ACCT_ID",),
    "CONT_MASTER": ("CONT_ID",),
    "ORD_HEADER": ("ORD_ID",),
    "ORD_LINE": ("ORD_ID", "LINE_NO"),
}

_CENTS = Decimal("0.01")


def _is_blank(value: Any) -> bool:
    return value is None or (isinstance(value, str) and value.strip() == "")


def _normalize_numeric(value: Any, monetary: bool) -> Any:
    if value == "":
        value = 0

    if value is None:
        return None

    if monetary:
        number = Decimal(str(value)).quantize(_CENTS, rounding=ROUND_HALF_UP)
        return format(number, ".2f")

    if isinstance(value, Decimal):
        return format(value, "f")

    return value


def _normalize_value(column: str, value: Any) -> Any:
    if column in _DATE_COLUMNS and value == "00000000":
        return None

    if column in _BOOLEAN_COLUMNS and _is_blank(value):
        return "N"

    if column == "CURR_CD" and _is_blank(value):
        return "USD"

    if column in _NUMERIC_COLUMNS:
        return _normalize_numeric(value, column in _MONETARY_COLUMNS)

    return value


def _normalize_row(table: str, source: dict) -> dict[str, Any]:
    return {
        column: _normalize_value(column, source.get(column))
        for column in _COLUMNS[table]
    }


def _numeric_sort_value(value: Any) -> tuple[int, Any]:
    if value is None:
        return (0, Decimal(0))
    try:
        return (1, Decimal(str(value)))
    except Exception:
        return (2, str(value))


def _sort_key(table: str, row: dict[str, Any]) -> tuple:
    key_parts = []
    for column in _PRIMARY_KEYS[table]:
        value = row[column]
        if column == "LINE_NO":
            key_parts.append(_numeric_sort_value(value))
        else:
            key_parts.append("" if value is None else str(value))
    return tuple(key_parts)


def _live_rows(table: str, rows: list[dict]) -> list[dict[str, Any]]:
    normalized = [
        _normalize_row(table, row)
        for row in rows
        if row.get("DEL_FLG") != "Y"
    ]
    normalized.sort(key=lambda row: _sort_key(table, row))
    return normalized


def load(
    conn: sqlite3.Connection,
    tables: dict[str, list[dict]],
) -> dict[str, int]:
    if conn.in_transaction:
        conn.commit()

    conn.execute("PRAGMA foreign_keys = ON")
    enabled = conn.execute("PRAGMA foreign_keys").fetchone()
    if enabled is None or enabled[0] != 1:
        raise RuntimeError("SQLite foreign-key enforcement could not be enabled")

    schema_path = Path(__file__).with_name("modern_schema.sql")
    conn.executescript(schema_path.read_text(encoding="utf-8"))

    prepared = {
        table: _live_rows(table, tables.get(table, []))
        for table in _TABLE_ORDER
    }
    inserted = {table: 0 for table in _TABLE_ORDER}

    try:
        conn.execute("BEGIN")

        for table in _TABLE_ORDER:
            columns = _COLUMNS[table]
            column_sql = ", ".join(columns)
            placeholders = ", ".join("?" for _ in columns)
            statement = (
                f"INSERT INTO {table} ({column_sql}) "
                f"VALUES ({placeholders})"
            )

            for row in prepared[table]:
                conn.execute(statement, tuple(row[column] for column in columns))
                inserted[table] += 1

        conn.commit()
    except Exception:
        conn.rollback()
        raise

    return inserted
